#!/usr/bin/env python3
"""Render the episode JSONs into a one-page-per-episode filming sheet.

Usage:  python tools/render_scripts.py
Output: content/SCRIPTS.md (gitignored — regenerate after any edit)
"""
from __future__ import annotations

from pathlib import Path
from typing import Any

from validate_content import ROOT, load_episodes


def build_markdown(episodes: list[tuple[Path, dict[str, Any]]]) -> str:
    lines = [
        "# FILMING SHEETS — English Educational Shorts",
        "",
        "Generated from `content/episodes/*.json`. Do not edit this file; edit the JSON.",
        "Read the VO out loud with a timer. If you have to rush, cut words, don't speed up.",
        "",
        "---",
        "",
    ]
    for path, ep in episodes:
        lines += [
            f"## {ep['id']} — {ep['topic']}",
            "",
            f"**Series:** {ep['series']} · **Duration:** {ep['duration_seconds']} s · "
            f"**Status:** {ep['status']} · **Fact-check:** "
            f"{'VERIFIED' if ep['fact_check']['verified'] else 'NOT VERIFIED — DO NOT PUBLISH'}",
            "",
            "### Hooks (film once, publish with the selected one; A/B the family next week)",
            "",
        ]
        for i, hook in enumerate(ep["hooks"]):
            mark = " ← SELECTED" if i == ep.get("selected_hook", 0) else ""
            lines.append(f"{i + 1}. {hook}{mark}")
        lines += ["", "### Titles", ""]
        for i, title in enumerate(ep["titles"]):
            lines.append(f"{i + 1}. {title}")
        lines += [
            "",
            "### Beat sheet",
            "",
            "| Time | VO (say exactly this) | On-screen | Visual / cut | Device |",
            "|---|---|---|---|---|",
        ]
        for b in ep["beats"]:
            def cell(value: str) -> str:
                return value.replace("|", "\\|").replace("\n", " ")
            lines.append(
                f"| `{b['t']}s` | {cell(b['vo'])} | {cell(b['on_screen'])} | "
                f"{cell(b['visual'])} | {b['device']} |"
            )
        lines += [
            "",
            f"**Payoff:** {ep['payoff']}",
            f"**CTA:** {ep['cta']}",
            f"**Pinned comment (post from the channel, then pin in Studio):** {ep['pinned_comment']}",
            f"**Thumbnail text:** {ep['thumbnail']['text']}",
            f"**Hashtags:** {' '.join(ep['hashtags'])}",
            f"**Verify before publishing:** {ep['fact_check']['source_hint']}",
            "",
            "**Description**",
            "",
            "```",
            ep["description"],
            "```",
            "",
            "---",
            "",
        ]
    return "\n".join(lines)


def main() -> int:
    episodes = load_episodes()
    out = ROOT / "content" / "SCRIPTS.md"
    out.write_text(build_markdown(episodes), encoding="utf-8")
    print(f"Wrote {out.relative_to(ROOT)} ({len(episodes)} episodes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
